INSERT INTO `landing_page_blocks` VALUES (507,3,'hero','hero','Header & Hero',NULL,NULL,1,1,'{\"image_url\":\"\",\"badge\":\"PDV inteligente para varejo moderno\",\"visual_mode\":\"mock\",\"visual_image_url\":\"\",\"login_url\":\"\\/app\\/login\",\"signup_url\":\"#pricing\",\"badges\":[\"Onboarding em menos de 24h\",\"Sem cartão de crédito no teste\",\"Suporte dedicado ao varejo\"],\"metrics\":[{\"value\":\"+18%\",\"label\":\"Aumento médio no faturamento\"},{\"value\":\"3x\",\"label\":\"Mais agilidade no caixa\"}],\"floating_widgets_enabled\":1,\"floating_widgets\":[{\"title\":\"Vendas em tempo real\",\"value\":\"+3 novas vendas\",\"icon\":\"bi bi-lightning-charge\",\"bg_color\":\"#0f172a\",\"text_color\":\"#f8fafc\",\"anchor\":\"top\",\"offset\":18},{\"title\":\"Alerta de estoque\",\"value\":\"4 itens abaixo do mínimo\",\"icon\":\"bi bi-exclamation-triangle\",\"bg_color\":\"#0f172a\",\"text_color\":\"#f8fafc\",\"anchor\":\"bottom\",\"offset\":8}]}','2025-12-27 18:47:11','2025-12-27 18:47:30'),(508,3,'features','feature_grid','Funcionalidades (Cards)',NULL,NULL,2,1,'{\"title\":\"Tudo o que o seu PDV precisa em um só lugar.\",\"subtitle\":\"<p>Substitua planilhas e sistemas antigos por um PDV pensado para o dia a dia do varejo: rápido no caixa, poderoso na gestão.<\\/p>\",\"cards\":[{\"icon\":\"bi bi-bag-check\",\"icon_color\":\"#10b981\",\"title\":\"Vendas omnichannel\",\"body\":\"<p>Registre vendas na loja física e online com o mesmo PDV, controle cupons, descontos e formas de pagamento em poucos cliques.\\\\r\\\\n\\\\r\\\\n<\\/p><ul><li>Histórico completo de clientes<\\/li><li>Integração com e-commerce<\\/li><li>Carrinho rápido para balcão<\\/li><\\/ul>\",\"tag\":\"Operação\"},{\"icon\":\"bi bi-cash-coin\",\"icon_color\":\"#0284c7\",\"title\":\"Caixa sem erro\",\"body\":\"<p>Abertura, fechamento e conferência de caixa com trilha auditável, evitando diferenças e retrabalho na rotina da equipe.\\\\r\\\\n\\\\r\\\\n<\\/p><ul><li>Fechamento automático<\\/li><li>Controle de sangrias e suprimentos<\\/li><li>Alertas de divergência em tempo real<\\/li><\\/ul>\",\"tag\":\"Gestão\"},{\"icon\":\"bi bi-box-seam\",\"icon_color\":\"#b45309\",\"title\":\"Estoque em ordem\",\"body\":\"<p>Acompanhe entradas, saídas, perdas e transferências com precisão, evitando ruptura e excesso de estoque.\\\\r\\\\n\\\\r\\\\n<\\/p><ul><li>Kits, grades e variações<\\/li><li>Alertas de mínimo e máximo<\\/li><li>Inventário guiado por leitor de código<\\/li><\\/ul>\",\"tag\":\"Diretoria\"},{\"icon\":\"bi bi-graph-up\",\"icon_color\":\"#4f46e5\",\"title\":\"Financeiro conectado\",\"body\":\"<p>Tenha visão clara de recebíveis, despesas, DRE simplificada e fluxo de caixa projetado por loja ou unidade.\\\\r\\\\n\\\\r\\\\n<\\/p><ul><li>Conciliação de cartões<\\/li><li>Relatórios em um clique<\\/li><li>Exportação para contabilidade<\\/li><\\/ul>\",\"tag\":\"Financeiro\"},{\"icon\":\"\",\"icon_color\":\"#10b981\",\"title\":\"\",\"body\":\"<p><br><\\/p>\",\"tag\":\"\"}]}','2025-12-27 18:47:11','2025-12-27 18:47:30'),(509,3,'demo','demo','Demonstração / Mockup',NULL,NULL,3,1,'{\"title\":\"Uma tela de PDV pensada para velocidade e simplicidade.\",\"subtitle\":\"<p>Visual clean, atalhos inteligentes e foco total na experiência do operador. Menos cliques, menos filas, mais vendas.<\\/p>\"}','2025-12-27 18:47:11','2025-12-27 18:47:30'),(510,3,'screenshots','screenshots','Galeria (Screenshots)',NULL,NULL,4,1,'{\"title\":\"Veja o PDV Loja por dentro.\",\"subtitle\":\"<p>Screenshots reais do sistema em uso. Adicione quantas telas quiser — o layout se ajusta automaticamente.<\\/p>\",\"display_mode\":\"grid\",\"frame\":\"browser\",\"lightbox\":0}','2025-12-27 18:47:11','2025-12-27 18:47:30'),(511,3,'testimonials','testimonials','Depoimentos',NULL,NULL,5,1,'{\"title\":\"Lojas reais, resultados concretos.\",\"subtitle\":\"<p>Varejistas de diferentes segmentos usam o PDV Loja para ganhar previsibilidade e escalar o negócio com segurança.<\\/p>\",\"items\":[{\"name\":\"Mariana Costa\",\"role\":\"Fundadora\",\"company\":\"Boutique Lumina\",\"text\":\"<p>“O PDV Loja reduziu em 70% o tempo de fechamento de caixa. Hoje consigo acompanhar vendas em tempo real do celular.”<\\/p>\",\"avatar_url\":\"\"},{\"name\":\"João Ribeiro\",\"role\":\"Diretor\",\"company\":\"Rede SuperFácil\",\"text\":\"<p>“Conseguimos unificar as vendas das lojas físicas e do e-commerce. A visão de estoque nunca foi tão clara.”<\\/p>\",\"avatar_url\":\"\"},{\"name\":\"Ana Lima\",\"role\":\"CEO\",\"company\":\"TechCell Store\",\"text\":\"<p>“Migrar de um sistema legado para o PDV Loja foi simples. Em uma semana, toda a operação já estava rodando 100%.”<\\/p>\",\"avatar_url\":\"\"},{\"name\":\"\",\"role\":\"\",\"company\":\"\",\"text\":\"<p><br><\\/p>\",\"avatar_url\":\"\"}]}','2025-12-27 18:47:11','2025-12-27 18:47:30'),(512,3,'about','about','Sobre / Missão',NULL,NULL,6,1,'{\"title\":\"Feito para quem vive o varejo na prática.\",\"body\":\"<p>O PDV Loja nasceu da união entre tecnologia SaaS e a experiência de quem já passou anos atrás do balcão. Nosso foco é tirar a complexidade da sua frente e colocar informação de qualidade na sua mão.<\\/p><p><br><\\/p><p>Com uma arquitetura em nuvem, atualizações constantes e segurança de nível bancário, você foca em vender enquanto nós cuidamos da infraestrutura.<\\/p>\",\"highlights\":[{\"title\":\"Arquitetura SaaS 100% em nuvem\",\"body\":\"<p>Escalável, resiliente e pronta para crescer com a sua rede.<\\/p>\"},{\"title\":\"Foco em experiência do operador\",\"body\":\"<p>Interface pensada para reduzir erros e treinamento.<\\/p>\"},{\"title\":\"Time especialista em varejo\",\"body\":\"<p>Onboarding guiado por quem conhece sua realidade.<\\/p>\"},{\"title\":\"\",\"body\":\"<p><br><\\/p>\"},{\"title\":\"\",\"body\":\"<p><br><\\/p>\"},{\"title\":\"\",\"body\":\"<p><br><\\/p>\"},{\"title\":\"\",\"body\":\"<p><br><\\/p>\"}]}','2025-12-27 18:47:11','2025-12-29 18:13:29'),(513,3,'pricing','pricing','Planos',NULL,NULL,7,1,'{\"title\":\"Planos que crescem com a sua loja.\",\"subtitle\":\"<p>Comece enxuto, escale quando precisar. Todos os planos incluem suporte especializado, atualizações contínuas e backup automático.<\\/p>\",\"cards\":[{\"label\":\"Start Loja\",\"tagline\":\"Ideal para começar\",\"icon\":\"fa fa-store\",\"theme\":\"soft\",\"featured\":0,\"use_system_plan\":1,\"plan_id\":1,\"custom_price\":\"129,00\",\"full_price\":\"197\",\"cta_label\":\"Começar com o Start\",\"cta_link\":\"#newsletter\",\"cta_mode\":\"checkout\",\"features\":[\"1 PDV físico\",\"Usuários ilimitados\",\"Gestão básica de estoque\",\"Relatórios essenciais de vendas\"]},{\"label\":\"Pro Varejo\",\"tagline\":\"Mais vendido\",\"icon\":\"fa fa-chart-line\",\"theme\":\"primary\",\"featured\":1,\"use_system_plan\":0,\"plan_id\":null,\"custom_price\":\"259,00\",\"full_price\":\"\",\"cta_label\":\"Testar o plano Pro\",\"cta_link\":\"#newsletter\",\"cta_mode\":\"link\",\"features\":[\"Até 3 PDVs físicos\",\"Controle avançado de estoque\",\"Fluxo de caixa e DRE simplificada\",\"Integração com e-commerce\"]},{\"label\":\"Enterprise Rede\",\"tagline\":\"Para redes e franquias\",\"icon\":\"fa fa-building\",\"theme\":\"dark\",\"featured\":0,\"use_system_plan\":0,\"plan_id\":null,\"custom_price\":\"\",\"full_price\":\"\",\"cta_label\":\"Falar com o time de vendas\",\"cta_link\":\"#contact\",\"cta_mode\":\"link\",\"features\":[\"PDVs ilimitados\",\"Camadas avançadas de permissão\",\"API e integrações personalizadas\",\"Gerente de conta dedicado\"]}]}','2025-12-27 18:47:11','2025-12-29 18:13:29'),(514,3,'faq','faq','FAQ',NULL,NULL,8,1,'{\"title\":\"Perguntas frequentes.\",\"subtitle\":\"<p>Transparência total antes de você decidir. Se algo não estiver aqui, nosso time terá o maior prazer em te ajudar.<\\/p>\",\"items\":[{\"question\":\"Preciso instalar algo na minha máquina?\",\"answer\":\"<p>Não. O PDV Loja é 100% em nuvem e roda diretamente no navegador. Para uso no caixa, recomendamos um computador com conexão estável à internet.<\\/p>\"},{\"question\":\"O período de teste é realmente sem compromisso?\",\"answer\":\"<p>Sim. Você testa por 14 dias com todas as funcionalidades do plano Pro e só adiciona forma de pagamento se decidir continuar.<\\/p>\"},{\"question\":\"Consigo migrar meus dados do sistema atual?\",\"answer\":\"<p>Sim. Nosso time auxilia na importação de cadastros de produtos, clientes e saldos de estoque a partir de planilhas ou do seu sistema anterior.<\\/p>\"},{\"question\":\"Como funciona o suporte?\",\"answer\":\"<p>Oferecemos suporte via chat, e-mail e WhatsApp em horário comercial, além de uma base de conhecimento completa com vídeos e tutoriais.<\\/p>\"}]}','2025-12-27 18:47:11','2025-12-27 18:47:30'),(515,3,'newsletter','newsletter','Newsletter & Contato',NULL,NULL,9,1,'{\"title\":\"Pronto para modernizar o PDV da sua loja?\",\"subtitle\":\"<p>Preencha seus dados e nosso time vai te acompanhar em cada passo da implantação. Sem letra miúda, sem surpresa na fatura.<\\/p>\"}','2025-12-27 18:47:11','2025-12-27 18:47:30'),(516,3,'footer','footer','Rodapé',NULL,NULL,10,1,'{\"text\":\"© 2025 PDV Loja. Todos os direitos reservados.\",\"logo_url\":\"\"}','2025-12-27 18:47:11','2025-12-27 18:47:30');
