INSERT INTO `pos_templates` VALUES (1,'Padrão','<section class=\"receipt-template\">\r\n\r\n    <header class=\"receipt-header\">\r\n        <div class=\"logo-area\">\r\n            <img class=\"logo\" src=\"{{ logo_url }}\">\r\n        </div>\r\n        <h2 class=\"store-name\">{{ store_name }}</h2>\r\n        <div class=\"address-area\">\r\n            <span class=\"info address\">{{ store_address }}</span>\r\n            <div class=\"block\">\r\n                <span class=\"info phone\">Cel: {{ store_phone }}</span>\r\n            </div>\r\n        \r\n    </header>\r\n\r\n   <section class=\"info-area\">\r\n            <table>\r\n                <tr>\r\n                    <td class=\"w-10\"><span>ID:</td>\r\n                    <td class=\"w-40 text-center sinfo billno\"><span>{{ invoice_id }}</span></td>\r\n                </tr>\r\n   </section>\r\n<br>\r\n    <h4 class=\"main-title\" style=\"text-align: center; margin-top: 5px;\">COMPROVANTE DE VENDA</h4>\r\n\r\n    <section class=\"sub-title\">\r\n            <table>\r\n                <thead>\r\n                    <tr>\r\n                        <td class=\"w-10 text-center\">Sl.</td>\r\n                        <td class=\"w-40 text-center\">Nome</td>\r\n                        <td class=\"w-15 text-center\">Qty</td>\r\n                        <td class=\"w-15 text-right\">Preço</td>\r\n                        \r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    {{ items }}\r\n                        <tr>\r\n                            <td class=\"text-center\">{{ sl }}</td>\r\n                            <td>{{ item_name }} \r\n                                {{ if invoice_view == indian_gst }} \r\n                                    <small>[HSN-{{ hsn_code }}]</small>\r\n                                {{ endif }}\r\n                            </td>\r\n                            <td class=\"text-center\">{{ item_quantity }} {{ unitName }}</td>\r\n                            <td class=\"text-right\">{{ item_price }}</td>\r\n                               \r\n                        </tr>\r\n                    {{ /items }}\r\n                </tbody>\r\n            </table>\r\n        </section>\r\n        \r\n    <section class=\"info-area calculation-area\" style=\"border-top: 1px dashed #000; margin-top: 5px; padding-top: 5px;\">\r\n        <table>\r\n            <tr>\r\n                <td class=\"w-70\">Subtotal:</td>\r\n                <td class=\"w-30 text-right\">{{ subtotal }}</td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"w-70\">Desconto:</td>\r\n                <td class=\"w-30 text-right\">{{ discount_amount }}</td>\r\n            </tr>\r\n            <tr>\r\n                <td class=\"w-70\">FRETE:</td>\r\n                <td class=\"w-30 text-right\">{{ shipping_amount }}</td>\r\n            </tr>\r\n            <tr style=\"font-weight: bold;\">\r\n                <td class=\"w-70\">TOTAL PAGO:</td>\r\n                <td class=\"w-30 text-right\">{{ paid_amount }}</td>\r\n            </tr>\r\n            \r\n            </tr>\r\n        </table>\r\n    </section>\r\n<br>\r\n    <section class=\"listing-area payment-list\">\r\n        <h4 class=\"main-title\" style=\"text-align: center; margin-top: 5px;\">Forma de Pagamento</h4>\r\n\r\n        <table>\r\n            <tbody>\r\n                {{payments}}\r\n                <tr>\r\n                    <td class=\"w-50\">{{ name }}:</td>\r\n                    <td class=\"w-50 text-right\">{{ amount }}</td>\r\n                </tr>\r\n                {{/payments}}\r\n            </tbody>\r\n        </table>\r\n       \r\n    </section>\r\n    \r\n\r\n    <section class=\"info-area align-center footer-area\" style=\"text-align: center; border-top: 0px dashed #000; margin-top: 10px; padding-top: 10px;\">\r\n       <span class=\"block\">Não fazemos Trocas de Produtos comprados na Loja Física.</span>\r\n            <span class=\"block bold\">Obrigado por nos escolher.</span>\r\n\r\n        <div class=\"qrcode-area\" style=\"margin-top: 10px;\">\r\n            {{ qrcode }}\r\n        </div>\r\n\r\n        <span style=\"font-size: 10px;\">Impresso em: {{ printed_on }} por {{ cashier_name }}</span>\r\n    </section>\r\n\r\n</section>                                        ','/*Common CSS*/\r\n{\r\n  margin: 0;\r\n  padding: 0;\r\n  box-sizing: border-box;\r\n}\r\n@media print {\r\n    body, html {\r\n        margin: 0;\r\n        padding: 0;\r\n        width: 100%;\r\n    }\r\n    .receipt-template { \r\n        width: 100%;   /* usa toda a largura da bobina */\r\n        margin: 0;     /* remove margens laterais */\r\n        padding: 0;    /* garante sem padding */\r\n    }\r\n}\r\n\r\n        .receipt-template {\r\n            width:220px;\r\n            margin:0 auto;\r\n        }\r\n        .receipt-template .text-small {\r\n            font-size: 10px;\r\n        }\r\n        .receipt-template .block {\r\n            display: block;\r\n        }\r\n        .receipt-template .inline-block {\r\n            display: inline-block;\r\n        }\r\n        .receipt-template .bold {\r\n            font-weight: 700;\r\n        }\r\n        .receipt-template .italic {\r\n            font-style: italic;\r\n        }\r\n        .receipt-template .align-right {\r\n            text-align: right;\r\n        }\r\n        .receipt-template .align-center {\r\n            text-align: center;\r\n        }\r\n        .receipt-template .main-title {\r\n            font-size: 12px;\r\n            font-weight: 700;\r\n            text-align: center;\r\n            margin: 10px 0 5px 0;\r\n            padding: 0;\r\n        }\r\n        .receipt-template .heading {\r\n            position: relation;\r\n        }\r\n        .receipt-template .title {\r\n            font-size: 14px;\r\n            font-weight: 700;\r\n            margin: 10px 0 5px 0;\r\n        }\r\n        .receipt-template .sub-title {\r\n            font-size: 10px;\r\n            font-weight: 700;\r\n            margin: 10px 0 5px 0;\r\n        }\r\n        .receipt-template table {\r\n            width: 100%;\r\n        }\r\n        .receipt-template td,\r\n        .receipt-template th {\r\n            font-size:10px;\r\n        }\r\n        .receipt-template .info-area {\r\n            font-size: 10px;      \r\n            line-height: 1.222;  \r\n        }\r\n        .receipt-template .listing-area {\r\n            line-height: 1.222;\r\n        }\r\n        .receipt-template .listing-area table {}\r\n        .receipt-template .listing-area table thead tr {\r\n            border-top: 1px solid #000;\r\n            border-bottom: 1px solid #000;\r\n            font-weight: 700;\r\n        }\r\n        .receipt-template .listing-area table tbody tr {\r\n            border-top: 1px dashed #000;\r\n            border-bottom: 1px dashed #000;\r\n        }\r\n        .receipt-template .listing-area table tbody tr:last-child {\r\n            border-bottom: none;\r\n        }\r\n        .receipt-template .listing-area table td {\r\n            vertical-align: top;\r\n        }\r\n        .receipt-template .info-area table {}\r\n        .receipt-template .info-area table thead tr {\r\n            border-top: 1px solid #000;\r\n            border-bottom: 1px solid #000;\r\n        }\r\n    \r\n /*Receipt Heading*/\r\n        .receipt-template .receipt-header {\r\n            text-align: center;\r\n        }\r\n        .receipt-template .receipt-header .logo-area {\r\n            width: 90px;\r\n            height: 90px;\r\n            margin: 0 auto;\r\n        }\r\n        .receipt-template .receipt-header .logo-area img.logo {\r\n            display: inline-block;\r\n            max-width: 100%;\r\n            max-height: 100%;\r\n        }\r\n        .receipt-template .receipt-header .address-area {\r\n            margin-bottom: 5px;\r\n            line-height: 1;\r\n        }\r\n        .receipt-template .receipt-header .info {\r\n            font-size: 10px;\r\n        }\r\n        .receipt-template .receipt-header .store-name {\r\n            font-size: 20px;\r\n            font-weight: 700;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n        \r\n        \r\n/*Invoice Info Area*/ \r\n    .receipt-template .invoice-info-area {}\r\n       .receipt-template .zero-around {\r\n            margin:0;\r\n            padding: 0;\r\n        }\r\n        .receipt-template .title-lg {\r\n            font-size: 18px!important;\r\n            margin-bottom: 5px;\r\n         }\r\n         .receipt-template .text-lg {\r\n             font-size: 18px;\r\n             font-weight: 700;\r\n         }\r\n         .receipt-template .info-area td {\r\n             vertical-align: center;\r\n         }\r\n         .receipt-template .info-area td.sinfo {\r\n             padding: 1px!important;\r\n         }\r\n         .receipt-template .info-area td.sinfo span {\r\n             display: block;\r\n             font-weight: 700;\r\n             border: 1px solid #000;\r\n             padding: 2px;\r\n         }\r\n/*Customer Customer Area*/\r\n    .receipt-template .customer-area {\r\n        margin-top:10px;\r\n    }\r\n\r\n/*Calculation Area*/\r\n    .receipt-template .calculation-area {\r\n        border-top: 2px solid #000;\r\n        font-weight: bold;\r\n    }\r\n    .receipt-template .calculation-area table td {\r\n        text-align: right;\r\n    }\r\n    .receipt-template .calculation-area table td:nth-child(2) {\r\n        border-bottom: 1px dashed #000;\r\n    }\r\n\r\n/*Item Listing*/\r\n    .receipt-template .item-list table tr {\r\n    }\r\n    \r\n/*Barcode Area*/\r\n    .receipt-template .barcode-area {\r\n        margin-top: 10px;\r\n        text-align: center;\r\n    }\r\n    .receipt-template .barcode-area img {\r\n        max-width: 100%;\r\n        display: inline-block;\r\n    }\r\n    \r\n/*Footer Area*/\r\n    .receipt-template .footer-area {\r\n        line-height: 1.222;\r\n        font-size: 10px;\r\n    }\r\n \r\n/*Media Query*/\r\n    @media print {\r\n        .receipt-template {\r\n            width: 110%;\r\n        }\r\n    }\r\n    @media all and (max-width: 315px) {}\r\n    \r\n    \r\n    /* ============================\r\n   OVERRIDES — manter tudo do CSS anterior e aplicar linhas retas externas\r\n   Cole este bloco ao final do seu arquivo CSS (não remova nada acima)\r\n   ============================ */\r\n\r\n/* garantir colapso de bordas (não altera regras existentes, apenas adiciona comportamento útil) */\r\n.receipt-template table {\r\n    border-collapse: collapse;\r\n    border-spacing: 0;\r\n}\r\n\r\n/* Forçar bordas sólidas superiores/inferiores nas caixas de listagem */\r\n/* Aplica a blocos já existentes: .listing-area e também explicitamente a .sub-title (caso seja usada como section) e .payment-list */\r\n.receipt-template .listing-area,\r\n.receipt-template .payment-list,\r\n.receipt-template .sub-title {\r\n    /* Mantém margens/paddings existentes; apenas adiciona as bordas sólidas externas */\r\n    border-top: 1px solid #000;\r\n    border-bottom: 1px solid #000;\r\n}\r\n\r\n/* Se o título do bloco (ex: <h4 class=\"sub-title\">) estiver sendo usado como elemento do bloco,\r\n   garante que não seja sobrescrito por regras anteriores que só afetem tabelas. */\r\n.receipt-template h4.sub-title,\r\n.receipt-template h4.payment-title {\r\n    border-top: none;  /* evita duplicar múltiplas bordas visuais no elemento título */\r\n    border-bottom: none;\r\n    margin: 6px 0;\r\n    padding: 6px 0;\r\n    text-align: center;\r\n    font-weight: 700;\r\n}\r\n\r\n/* Caso existam regras que aplicam \"border-top/bottom: dashed\" a <tr> do tbody,\r\n   mantemos essas divisões internas, mas garantimos que as bordas externas permaneçam sólidas. */\r\n/* Se quiser remover as linhas tracejadas internas e deixar tudo sólido, descomente as linhas abaixo:\r\n.receipt-template .listing-area table tbody tr,\r\n.receipt-template .payment-list table tbody tr {\r\n    border-top: 1px solid #000;\r\n    border-bottom: 1px solid #000;\r\n}\r\n*/\r\n\r\n/* Pequeno ajuste de espaçamento para não encostar nas linhas sólidas externas */\r\n.receipt-template .listing-area table,\r\n.receipt-template .payment-list table {\r\n    margin-top: 6px;\r\n    margin-bottom: 6px;\r\n}\r\n\r\n/* Garante que a caixa do número (ID) continue com a borda sólida (preserva seu estilo já existente) */\r\n.receipt-template .info-area td.sinfo span {\r\n    border: 1px solid #000; /* esta regra já existe no seu CSS; aqui apenas reforçamos caso haja sobreposições */\r\n}\r\n\r\n/* Segurança: evita que regras muito genéricas sobrescrevam estas bordas externas.\r\n   Não use !important a não ser que realmente precise. Se depois algo ainda não aplicar,\r\n   me diga e eu ajusto a especificidade. */\r\n                    ','2019-05-10 12:35:05','2026-01-22 17:10:28',1),(3,'Minimalista','<div class=\"receipt-minimal\">\r\n  <div class=\"receipt-header\">\r\n    <div class=\"logo-section\">\r\n      {{ logo }}\r\n    </div>\r\n    <h2 class=\"store-name\">{{ store_name }}</h2>\r\n    <div class=\"store-info\">\r\n      <p>{{ store_address }}</p>\r\n      <p>{{ store_phone }} • {{ store_email }}</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"divider\"></div>\r\n\r\n  <div class=\"invoice-info\">\r\n    <div class=\"invoice-row\">\r\n      <span class=\"label\">Fatura:</span>\r\n      <span class=\"value\">#{{ invoice_id }}</span>\r\n    </div>\r\n    <div class=\"invoice-row\">\r\n      <span class=\"label\">Data:</span>\r\n      <span class=\"value\">{{ date_time }}</span>\r\n    </div>\r\n    <div class=\"invoice-row\">\r\n      <span class=\"label\">Cliente:</span>\r\n      <span class=\"value\">{{ customer_name }}</span>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"divider\"></div>\r\n\r\n  <div class=\"items-section\">\r\n    <table class=\"items-table\">\r\n     