ceipt-minimal {\r\n  max-width: 300px;\r\n  margin: 0 auto;\r\n  padding: 20px;\r\n  font-family: \'Courier New\', Courier, monospace;\r\n  background: #ffffff;\r\n  color: #1a1a1a;\r\n  line-height: 1.6;\r\n}\r\n\r\n/* Header */\r\n.receipt-header {\r\n  text-align: center;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.logo-section {\r\n  margin-bottom: 15px;\r\n}\r\n\r\n.logo-section img {\r\n  max-width: 120px;\r\n  height: auto;\r\n}\r\n\r\n.store-name {\r\n  font-size: 20px;\r\n  font-weight: bold;\r\n  margin: 10px 0;\r\n  text-transform: uppercase;\r\n  letter-spacing: 1px;\r\n}\r\n\r\n.store-info {\r\n  font-size: 11px;\r\n  color: #666;\r\n  margin-top: 8px;\r\n}\r\n\r\n.store-info p {\r\n  margin: 3px 0;\r\n}\r\n\r\n/* Divider */\r\n.divider {\r\n  border-top: 1px dashed #333;\r\n  margin: 15px 0;\r\n}\r\n\r\n/* Invoice Info */\r\n.invoice-info {\r\n  margin-bottom: 15px;\r\n}\r\n\r\n.invoice-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  font-size: 12px;\r\n  margin: 5px 0;\r\n}\r\n\r\n.invoice-row .label {\r\n  font-weight: bold;\r\n}\r\n\r\n.invoice-row .value {\r\n  text-align: right;\r\n}\r\n\r\n/* Items Table */\r\n.items-section {\r\n  margin: 15px 0;\r\n}\r\n\r\n.items-table {\r\n  width: 100%;\r\n  border-collapse: collapse;\r\n  font-size: 11px;\r\n}\r\n\r\n.items-table thead {\r\n  border-bottom: 1px solid #333;\r\n}\r\n\r\n.items-table th {\r\n  text-align: left;\r\n  padding: 5px 2px;\r\n  font-weight: bold;\r\n  font-size: 11px;\r\n}\r\n\r\n.items-table th:nth-child(2),\r\n.items-table th:nth-child(3),\r\n.items-table th:nth-child(4) {\r\n  text-align: right;\r\n}\r\n\r\n.items-table td {\r\n  padding: 8px 2px;\r\n  border-bottom: 1px dotted #ddd;\r\n}\r\n\r\n.items-table td:nth-child(2),\r\n.items-table td:nth-child(3),\r\n.items-table td:nth-child(4) {\r\n  text-align: right;\r\n}\r\n\r\n/* Totals */\r\n.totals-section {\r\n  margin: 15px 0;\r\n}\r\n\r\n.total-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n 